-- French for story/story_*.lua; a missing key shows the English.

local T = {}

T["You find yourself walking through the quaint Fox Village in the forest."] = "Tu te promènes dans le pittoresque Village des Renards, au cœur de la forêt."
T["It's a cloudy day, painting the town in a tone of gray."] = "Le ciel est couvert, et le village se teinte de gris."
T["Suddenly, you hear footsteps coming your way, and an impact against you blows you to the ground!"] = "Soudain, tu entends des pas venir vers toi, puis quelque chose te percute et t’envoie au tapis !"
