T["Hey Boss! {pause:0.4}\nAre you ready to take on the pagoda again?"] = "Hé, Chef ! {pause:0.4}\nOn repart à l’assaut de la pagode ?"
T["Sure am!"] = "Et comment !"
T["Boss???"] = "Chef ???"
